Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Module RlDec2.
Import Ltac2.Ltac2 Ltac2.Constr.

Ltac2 rl_step () : constr := constr:(@OSSVerify.Proofs.leptonica.bilateral_fuzzer.lib.K5.Lib.StepFast.sf_evt_step).
Ltac2 fail (s : string) := Control.throw (Tactic_failure (Some (Message.of_string (String.app "RlDec2: " s)))).

Ltac2 decoded (w : constr) : constr * constr :=
  let d := Std.eval_vm None constr:(decode_any $w) in
  match Constr.Unsafe.kind d with
  | Constr.Unsafe.App _ sargs =>
    match Constr.Unsafe.kind (Array.get sargs 1) with
    | Constr.Unsafe.App _ pargs => (Array.get pargs 2, Array.get pargs 3)
    | _ => fail "decode_any gave no pair"
    end
  | _ => fail "decode_any gave None"
  end.

Ltac2 last_arg (c : constr) : constr :=
  match Constr.Unsafe.kind c with
  | Constr.Unsafe.App _ xs => Array.get xs (Int.sub (Array.length xs) 1)
  | _ => fail "not an application"
  end.
Ltac2 app (f : constr) (xs : constr array) : constr := Constr.Unsafe.make (Constr.Unsafe.App f xs).

Ltac2 hexec (h16 : constr) (a : constr) (imm : constr) : constr :=
  match Constr.Unsafe.kind h16 with
  | Constr.Unsafe.App cong cargs =>
    if Int.equal (Array.length cargs) 5 then
      let traw := Array.get cargs 2 in
      let tnorm := Array.get cargs 3 in
      match Constr.Unsafe.kind traw with
      | Constr.Unsafe.App alu xs =>
        if Int.equal (Array.length xs) 3 then
          match Constr.Unsafe.kind (Array.get xs 2) with
          | Constr.Unsafe.App sx ys =>
            let n := match Constr.Unsafe.kind imm with
              | Constr.Unsafe.App _ bs => Array.get bs 0
              | _ => fail "immediate is no bv literal" end in
            let ys2 := Array.copy ys in
            Array.set ys2 (Int.sub (Array.length ys2) 1) imm;
            let traw2 := app alu [| Array.get xs 0; a; app sx ys2 |] in
            let mid := app constr:(@OSSVerify.Proofs.leptonica.bilateral_fuzzer.lib.K5.Common.PropExec.v_addi) [| a; app constr:(@stdpp.bitvector.definitions.bv_signed) [| n; imm |] |] in
            let hj := app constr:(@eq_trans) [| constr:(word); traw2; mid; tnorm;
                                               app constr:(@OSSVerify.Proofs.leptonica.bilateral_fuzzer.lib.K5.Common.PropExec.alu_addi) [| a; n; imm |];
                                               app constr:(@eq_refl) [| constr:(word); tnorm |] |] in
            app cong [| Array.get cargs 0; Array.get cargs 1; traw2; tnorm; hj |]
          | _ => fail "traw's immediate is no application"
          end
        else fail "traw is no alu64 a b"
      | _ => fail "traw is no application"
      end
    else fail "execution fact is no sf_congT"
  | _ => fail "execution fact is no application"
  end.

Ltac2 rec rl_fix (hits : int Ref.ref) (f0 : constr) (ops : (constr * constr) list) (c : constr) : constr :=
  match Constr.Unsafe.kind c with
  | Constr.Unsafe.App f args =>
    let args := Array.of_list (List.map (rl_fix hits f0 ops) (Array.to_list args)) in
    let op :=
      if Constr.equal f f0 then
        if Int.equal (Array.length args) 18 then
          List.fold_left (fun acc (q, a) => match acc with Some _ => acc | None =>
            if Constr.equal q (Array.get args 4) then Some a else None end) None ops
        else None
      else None in
    match op with
    | Some a =>
      let (i, sz) := decoded (Array.get args 9) in
      Ref.set hits (Int.add (Ref.get hits) 1);
      Array.set args 10 i;
      Array.set args 11 sz;
      Array.set args 15 constr:(@eq_refl (option (instr * Z)) (@Some (instr * Z) (@pair instr Z $i $sz)));
      Array.set args 16 (hexec (Array.get args 16) a (last_arg i));
      Constr.Unsafe.make (Constr.Unsafe.App f args)
    | None => Constr.Unsafe.make (Constr.Unsafe.App (rl_fix hits f0 ops f) args)
    end
  | _ => Constr.Unsafe.map (rl_fix hits f0 ops) c
  end.

Ltac2 run1 (tab : string) (secs : string list) (s : string) (ops : (constr * constr) list) : unit :=
  KReplay.kr_revert ();
  let ph := Ref.ref [] in
  let c := KReplay.decode_ph (Some ph) tab (KReplay.kr_secs secs) s in
  let f0 := rl_step () in
  let hits := Ref.ref 0 in
  let c' := rl_fix hits f0 ops c in
  let bs := List.map (fun (e, b) => (e, rl_fix hits f0 ops b)) (Ref.get ph) in
  (if Int.equal (Ref.get hits) 0 then fail "no step at the listed pcs" else ());
  Std.exact_no_check c';
  List.iter (fun (e, b) => Control.new_goal e; Control.enter (fun () => Std.exact_no_check b)) bs.
End RlDec2.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
(* [comment removed for export] *)
Local Ltac norm_regset ::=
  repeat match goal with
  | |- context [@bvmap_set 5 word ?r ?v ?R] =>
      lazymatch R with TNode _ _ _ => idtac | TEmpty => idtac end;
      let p := eval vm_compute in (bv_key r) in
      change (@bvmap_set 5 word r v R) with (tset p v R);
      cbv beta iota delta [tset mkR]
  end.

Section PBG.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Hypothesis BC : bilateralCreate_cps2V RT.   (* [comment removed for export] *)
Hypothesis BA : bilateralApply_cpsV RT.
Hypothesis BD : bilateralDestroy_cps2 RT.
Hypothesis RERRP : returnError_cpsF RT e_returnErrorPtr.
Hypothesis LIT_BIL : exists l, In (0x2ad20, l) LEPT_LITS.
Hypothesis LIT_PN : exists l, In (0x2aca0, l) LEPT_LITS.
Hypothesis TRBC1 : Forall (fun f => In [f; 0xced24] CLIENT_TRACES) BC_CALLOC_RAS.
(* [comment removed for export] *)
Hypothesis TRBC3 : In [PGLP_CALLOC; RA_BC_LINEPTRS; 0xced24] CLIENT_TRACES.
Hypothesis TRBC4 : Forall (fun f => In [f; RA_BC_DESTROY; 0xced24] CLIENT_TRACES) DESTROY_FREE_RAS.
Hypothesis TRBC5 : In [PMCOPY_CALLOC1; 0x9fdc0; 0xa028c; RA_BC_AMB; 0xced24] CLIENT_TRACES.

Theorem pixBilateralGray_ok : pixBilateralGray_cps RT.
Proof using AF GP FKC BC BA BD RERRP LIT_BIL LIT_PN TRBC1 TRBC3 TRBC4 TRBC5.
Ltac fp_dec :=
      lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
        lazymatch c with context [reg_get] => fail "open FP condition" | _ => idtac end;
        let w := eval vm_compute in c in change c with w; cbv iota end.
Ltac fs_walk :=
        repeat first [ reflexivity
                     | progress (rewrite ?fs_reg_get_set; fs_eqb_simp)
                     | match goal with H : fs_agree ?F1 ?F2 |- context [reg_get ?F2 ?r] => rewrite (fs_agree_get F1 F2 r H) by reflexivity end ].
Ltac fs_agree_chain :=
        let r := fresh "r" in let Hr := fresh "Hr" in
        intros r Hr; apply fs_callee_cases in Hr; cbn [map In] in Hr;
        repeat (destruct Hr as [<-|Hr]); [..| destruct Hr]; fs_walk.
